253	static bool CheckUpsampleShape(const aclTensor* gradOut, const aclIntArray* outputSize, const aclIntArray* inputSize)
254	{
255	    size_t outputSizeNum = outputSize->Size();
256	    size_t inputSizeNum = inputSize->Size();
257	    OP_CHECK_WRONG_DIMENSION(gradOut, UPSAMPLE_DIM_LIMIT, return false);
258	    OP_CHECK(
259	        outputSizeNum == UPSAMPLE_EXPECT_SIZE,
260	        OP_LOGE(ACLNN_ERR_PARAM_INVALID, "It is expected output_size equals to 3, but got size %zu", outputSizeNum),
261	        return false);
262	
263	    OP_CHECK(inputSizeNum == UPSAMPLE_DIM_LIMIT,
264	             OP_LOGE(ACLNN_ERR_PARAM_INVALID, "It is expected input_size equals to 5, but got size %zu", inputSizeNum),
265	             return false);
266	    return true;
267	}
