269	// 循环判断size是否相等
270	static bool CheckSizeLoop(size_t dimNum, Shape gradOutShape, FVector<int64_t>& fullOutputSize)
271	{
272	    for (size_t i = 0; i < dimNum; ++i) {
273	        if (gradOutShape.GetDim(i) != fullOutputSize[i]) {
274	            OP_LOGE(ACLNN_ERR_PARAM_INVALID,
275	                    "Expected grad_output to have the same shape as output;"
276	                    " output.size(%zu) = %ld but got grad_output.size(%zu) = %ld",
277	                    i, fullOutputSize[i], i, gradOutShape.GetDim(i));
278	            return false;
279	        }
280	    }
281	    return true;
282	}
