284	static inline bool CheckInpuNullTensorMaxUnPool3D(const aclTensor* self)
285	{
286	    auto inputShape = self->GetViewShape();
287	    size_t dimNum = inputShape.GetDimNum();
288	
289	    for (size_t i = 1; i < dimNum; ++i) {
290	        if (inputShape.GetDim(i) <= 0) {
291	            OP_LOGE(ACLNN_ERR_PARAM_INVALID,
292	                    "max_unpool3d(): Expected input to have non-zero size for non-batch dimensions, "
293	                    "but got %zu with dimension %zu being empty.",
294	                    dimNum, i);
