18	
19	namespace {
20	std::unordered_set<uint64_t> g_allocated_ptr;
21	}
22	
23	namespace aicpu {
24	uint32_t CpuKernelAllocatorUtils::ParamCheck(const std::vector<int64_t>& dims, const void* data_ptr,
25	                                             Tensor*& output_result_tensor)
26	{
27	    if (dims.empty()) {
28	        KERNEL_LOG_ERROR("UpdateOutputDataTensor dims size == 0.");
29	        return KERNEL_STATUS_PARAM_INVALID;
30	    }
31	    KERNEL_CHECK_NULLPTR(output_result_tensor, KERNEL_STATUS_PARAM_INVALID, "output_result_tensor nullptr");
32	    KERNEL_CHECK_NULLPTR(data_ptr, KERNEL_STATUS_PARAM_INVALID, "data_ptr nullptr");
33	    return KERNEL_STATUS_OK;
34	}
35	
36	uint32_t CpuKernelAllocatorUtils::UpdateOutputDataTensor(const std::vector<int64_t>& dims, DataType type,
37	                                                         const void* data_ptr, int64_t input_data_size,
38	                                                         Tensor*& output_result_tensor)
39	{
40	    uint32_t check_ret = ParamCheck(dims, &data_ptr, output_result_tensor);
41	    if (check_ret != KERNEL_STATUS_OK) {
42	        return check_ret;
43	    }
44	    KERNEL_LOG_INFO("UpdateOutputDataTensor::START!!");
45	
46	    int64_t data_size = GetInputDataSize(dims, type);
47	    if (data_size < 0) {
48	        return KERNEL_STATUS_PARAM_INVALID;
49	    }
50	
51	    if (data_size > input_data_size) {
52	        KERNEL_LOG_ERROR("data_size[%ld] mast less than input_data_size[%ld]!", data_size, input_data_size);
53	        return KERNEL_STATUS_INNER_ERROR;
54	    }
55	
56	    int64_t shape_buff_size = 0;
57	    KERNEL_CHECK_ASSIGN_64S_MULTI(int64_t(dims.size()), int64_t(sizeof(int64_t)), shape_buff_size,
58	                                  KERNEL_STATUS_PARAM_INVALID);
59	
60	    void* output_shape_ptr = malloc(shape_buff_size);
61	    KERNEL_CHECK_NULLPTR(output_shape_ptr, KERNEL_STATUS_PARAM_INVALID, "malloc error, size[%ld]!", shape_buff_size);
62	
63	    int32_t ret = memcpy_s(output_shape_ptr, shape_buff_size, dims.data(), shape_buff_size);
64	    if (ret != EOK) {
65	        free(output_shape_ptr);
66	        KERNEL_LOG_ERROR("memcpy error, size[%ld], ret[%d]!", shape_buff_size, ret);
67	        return KERNEL_STATUS_INNER_ERROR;
68	    }
69	
70	    aicpu::FWKAdapter::ResultSummary* result_summary = reinterpret_cast<aicpu::FWKAdapter::ResultSummary*>(
71	        output_result_tensor->GetData());
72	    result_summary->raw_data_size = data_size;
73	    result_summary->shape_data_size = shape_buff_size;
74	
75	    if (data_size == 0) {
76	        result_summary->raw_data_ptr = reinterpret_cast<uint64_t>(nullptr);
77	        result_summary->shape_data_ptr = reinterpret_cast<uint64_t>(output_shape_ptr);
78	        (void)g_allocated_ptr.insert(result_summary->shape_data_ptr);
79	        KERNEL_LOG_INFO("UpdateOutputDataTensor:: empty tensor END!!");
80	        return KERNEL_STATUS_OK;
81	    }
82	
83	    void* output_data_ptr = malloc(data_size);
84	    if (output_data_ptr == nullptr) {
85	        KERNEL_LOG_ERROR("malloc error, size[%ld]!", data_size);
86	        free(output_shape_ptr);
87	        return KERNEL_STATUS_INNER_ERROR;
88	    }
89	
90	    ret = memcpy_s(output_data_ptr, data_size, data_ptr, data_size);
91	    if (ret != EOK) {
92	        free(output_data_ptr);
93	        free(output_shape_ptr);
94	        KERNEL_LOG_ERROR("memcpy_s error, size[%ld], ret[%d]!", data_size, ret);
95	        return KERNEL_STATUS_INNER_ERROR;
96	    }
97	
98	    result_summary->raw_data_ptr = reinterpret_cast<uint64_t>(output_data_ptr);
99	    result_summary->shape_data_ptr = reinterpret_cast<uint64_t>(output_shape_ptr);
100	    KERNEL_LOG_INFO("raw_data_ptr [%p]", output_data_ptr);
